#!/usr/bin/env python3
"""Round 27 (24 September): names for the Wageningen drivers of disturbance
alerts. Run from ~/Desktop/culprits. Safe to run twice."""
import base64, subprocess, sys, os, tempfile

DIFF = base64.b64decode("")
NOTE = """
## Round 27 (24 September): the eleven driver classes named

- `wur_integration_alert_drivers_class` now shows names, not Class 1 to 11.
  Pairing: GFW's map legend (Global Nature Watch, layer
  `drivers-of-deforestation-alert`) gives each name a colour; GFW's map code
  (wri/gfw, providers/datasets-provider/config.js, `alertDriversEncoded`)
  paints each number in one of those colours. Ten match exactly; class 3 is
  (244,177,131) in the code, (244,176,131) in the legend. Result: 1 Small-scale
  agriculture, 2 the same with fire, 3 Large-scale agriculture, 4 the same with
  fire, 5 Road development, 6 Selective logging, 7 Mining, 8 Flooding,
  9 Wildfire, 10 Other natural disturbances, 11 Unlabeled. 9 and 10 are the
  reverse of the legend's order.
- Each name's hover text is GFW's own card description (Flourish 25392464,
  embedded in GFW's blog post on the dataset). Colours stay the map's own.
"""

def git(*a):
    return subprocess.run(["git", *a], capture_output=True, text=True)

if not os.path.exists("map/app.js"):
    sys.exit("Run this from the culprits folder (cd ~/Desktop/culprits).")
with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
    f.write(DIFF); path = f.name
if git("apply", "--check", "-R", path).returncode == 0:
    print("Already applied. Nothing changed.")
else:
    r = git("apply", "--3way", path)
    if r.returncode != 0:
        print(r.stdout + r.stderr)
        git("checkout", "--", "map/app.js", "map/test.mjs")
        sys.exit("Did not apply; nothing changed. Run git pull --no-edit and try again, or send this message back.")
    print("Code changes applied.")
os.unlink(path)
h = open("HANDOFF.md", encoding="utf-8").read()
if "## Round 27 (24 September)" not in h:
    i = h.index("---") + 3
    open("HANDOFF.md", "w", encoding="utf-8").write(h[:i] + "\n" + NOTE + h[i:])
    print("HANDOFF.md note added.")
else:
    print("HANDOFF.md note already there.")
